using UnityEngine;

namespace GPA.TopDown2D
{
    /// <summary>
    /// Where pedestrians may walk, per map cell: sidewalks, park paths and crosswalks.
    /// Generated by the city builder alongside the tilemaps.
    /// </summary>
    public sealed class WalkMap2D : MonoBehaviour
    {
        public enum Kind : byte { Blocked = 0, Sidewalk = 1, Crosswalk = 2, Park = 3 }

        public static WalkMap2D Instance { get; private set; }

        public int Width, Height;
        public float CellSize = 4f;
        public Vector2 Origin;
        public byte[] Cells = new byte[0];

        private void Awake() => Instance = this;
        private void OnDestroy() { if (Instance == this) Instance = null; }

        public Kind At(Vector2Int c) =>
            c.x < 0 || c.y < 0 || c.x >= Width || c.y >= Height ? Kind.Blocked : (Kind)Cells[c.y * Width + c.x];

        public Vector2Int CellOf(Vector2 p) => new Vector2Int(Mathf.FloorToInt((p.x - Origin.x) / CellSize), Mathf.FloorToInt((p.y - Origin.y) / CellSize));
        public Vector2 Centre(Vector2Int c) => Origin + new Vector2((c.x + 0.5f) * CellSize, (c.y + 0.5f) * CellSize);
        public bool Walkable(Vector2Int c) => At(c) != Kind.Blocked;
    }
}
